const samples=[{name:'Blue mug',quantity:2},{name:'Field kit',quantity:1}];
const inline=samples.map(item=>({...item})), modal=samples.map(item=>({...item}));
const dialog=document.querySelector('dialog'), form=dialog.querySelector('form');
let active=0;
function render(){
 document.querySelector('#inline-items').replaceChildren(...inline.map((item,index)=>{
  const row=document.createElement('div');
  const summary=document.createElement('p');summary.textContent=`${item.name}, quantity ${item.quantity}`;
  const input=document.createElement('input');input.value=item.name;input.setAttribute('aria-label',`Inline name ${index+1}`);
  const error=document.createElement('p');error.className='error';error.setAttribute('role','alert');
  const save=document.createElement('button');save.textContent='Save';save.onclick=()=>{if(!input.value.trim()){error.textContent='Enter a name.';return;}item.name=input.value.trim();render();};
  const cancel=document.createElement('button');cancel.textContent='Cancel';cancel.onclick=render;
  row.append(summary,input,error,cancel,save);return row;
 }));
 document.querySelector('#dialog-items').replaceChildren(...modal.map((item,index)=>{
  const row=document.createElement('div'), summary=document.createElement('p'), edit=document.createElement('button');
  summary.textContent=`${item.name}, quantity ${item.quantity}`;edit.textContent=`Edit ${item.name}`;
  edit.onclick=()=>{active=index;dialog.querySelector('.item-summary').textContent=summary.textContent;form.elements.name.value=item.name;dialog.querySelector('.error').textContent='';document.body.classList.add('dialog-open');dialog.showModal();};
  row.append(summary,edit);return row;
 }));
}
function close(){dialog.close();document.body.classList.remove('dialog-open');}
form.noValidate=true;
form.onsubmit=event=>{event.preventDefault();const name=form.elements.name.value.trim();if(!name){dialog.querySelector('.error').textContent='Enter a name.';return;}modal[active].name=name;close();render();};
form.elements.name.oninput=()=>{dialog.querySelector('.error').textContent='';};
document.querySelector('#cancel').onclick=close;
dialog.oncancel=()=>document.body.classList.remove('dialog-open');
render();
